nta.declaration:
/*
*  --------- BEGIN CONFIGURATION SECTION
*/
const bool Debug_Mode = false;

const bool Periodic = true;

const double Sporadic_Interval = 40.0;

const int MaxTime = 45;
typedef int[0,MaxTime] time_t;

const int Tasks = 3;                 // Number of tasks/actors
typedef int[0,Tasks-1] t_id;

const int Procs = 3;                 // Number of resources
typedef int[0,Procs-1] r_id;

const int Dags = 1;                 // Number of resources
typedef int[0,Dags-1] d_id;

typedef int[-1, Dags*Tasks-1] g_id;

const int load_limit[Procs] = {5,6,90};

const int BufferSize = 2;
typedef int[0,Tasks-1] b_id;

typedef struct {
  bool sporadic;
  int number_tasks;
} dag_t;

typedef struct {
  time_t initial_offset;
  time_t min_period;
  time_t max_period;
  time_t offset;
  time_t deadline;
  time_t bcet;
  time_t wcet;
  r_id resources[Procs-1];
  int pri;
  int[0,1] type; // 0: task node, 1: communication node
  int curr_resource;

} task_t;

typedef struct {
  int[0,Tasks] length;
  t_id element[Tasks];
} buffer_t; 

buffer_t buffer[Procs];

// buffer_t ready_tasks[Dags*Tasks];

const int Policies      = 3;
const int EDF  		= 0;
const int FIFO 		= 1;
const int FPS  		= 2;

chan inserted, insert_task[Policies];
typedef int[0,Policies-1] policy_t;

const r_id res1[Procs-1] = {0,1};
const r_id res2[Procs-1] = {0,1};
const r_id bus[Procs-1] = {2,2};
const dag_t dag[Dags] = {
{false, 6}
};

//init_offset, min_period, max_period, offset, deadline, bcet, wcet, resource, priority, allowed resource, current resource
task_t task[Dags][Tasks] = {
    {
        {0, 2, 2, 0, 35, 2, 2, res1, 1, 0, 0},
        {0, 3, 3, 0, 35, 3, 3, res2, 1, 0, 0},
        {0, 2, 2, 0, 35, 2, 2, res2, 1, 0, 0}
    }
};

int edge_buffer[Dags][Tasks][Tasks] = {
    {
        { 0, 20, 20},
        { 20, 0, 20},
        { 20, 20, 0}
    }
};

const int prod[Dags][Tasks][Tasks]= {
    {
        { 0, 20, 20},
        { 20, 0, 20},
        { 20, 20, 0}
    }
};

const int cons[Dags][Tasks][Tasks]= {
    {
        { 0, 20, 20},
        { 20, 0, 20},
        { 20, 20, 0}
    }
};

/*
*  --------- END CONFIGURATION SECTION
*/
clock time[Dags][Tasks];//, exec[Tasks];
bool complete[Dags][Tasks];

/* debug variables */
bool error[Dags][Tasks];
int counter[Dags][Tasks];
int counter_resource[Procs];

urgent chan ready[Procs];
chan finished[Dags][Tasks];//run[Procs+1], stop[Procs], done[Procs];

/* scheduler */
broadcast chan resource_assigned[Dags][Tasks];
broadcast chan resource_not_found[Dags][Tasks];
broadcast chan request_resource[Dags][Tasks];

/*
    processor load tracking
    load[p] = sum of the costs of tasks currently assigned to p
    load_limit[p]
*/
int load[Procs];

meta struct {
  meta d_id dag;
  meta t_id task;
  meta r_id resource;
  meta bool preempt;
} param;

void setParams(d_id d, t_id t, r_id r, bool preempt) {
  param.dag = d; param.task = t; param.resource = r; param.preempt = preempt;
}

meta g_id ready_task;

void insert_at(int[0,Tasks] pos, t_id tid, r_id rid) {
  int i;
  for(i = buffer[rid].length; i > pos; i--) {
    buffer[rid].element[i] = buffer[rid].element[i-1];
  }
  if (Tasks == 1)
    pos = 0;

  buffer[rid].element[pos] = tid;
  buffer[rid].length++;

}

// to check if an actor 'a' of DAG 'd' can fire
bool can_fire(d_id did, t_id tid)
{
    int i;

    if (task[did][tid].type == 1 &&
        task[did][tid].curr_resource != bus[0])
    {
        return false;
    }

    // to fire, all incoming edges must have enough tokens
    for (i = 0; i < Tasks; i++)
    {
        if (cons[did][i][tid] > 0)
        {
            if (edge_buffer[did][i][tid] < cons[did][i][tid])
            {
                return false;
            }            
        }      
    }
    return true;
}
// consumes tokens from incoming edges and resets the actor's clock
void consume(d_id did, t_id tid)
{
    int i;
    if (Debug_Mode)
    {
        return;
    }
    if (task[did][tid].type == 1 &&
        task[did][tid].curr_resource != bus[0])
    {
        return;
    }
    for (i = 0; i < Tasks; i++)
    {
        if (cons[did][i][tid] > 0)
        {
            edge_buffer[did][i][tid] -= cons[did][i][tid];
        }
    }
    // reset clock do actor disparado
    // clk[d][a] = 0;
}
// produces tokens on outgoing edges. Called when an execution completes.
void produce(d_id did, t_id tid)
{
    int i;
    if (Debug_Mode)
    {
        return;
    }
    if (task[did][tid].type == 1 &&
        task[did][tid].curr_resource != bus[0])
    {
        return;
    }

    for (i = 0; i < Tasks; i++)
    {
        if (prod[did][tid][i] > 0)
        {
            edge_buffer[did][tid][i] += prod[did][tid][i];  
        }
    }
}

bool semaphore = false;

bool acquire_semaphore() {
    if (semaphore) {
        return false;
    }

    semaphore = true;

    return semaphore; 
}

bool release_semaphore() {

    semaphore = false;

    return semaphore; 
}

template.declaration:
int debug_ready_task = -1;

void removeTask() {
  int i = 0;
  buffer[id].length--;

  do {
    buffer[id].element[i] = buffer[id].element[i+1];
    i++;
  } while (i < buffer[id].length);
  buffer[id].element[buffer[id].length] = 0;
}

b_id front() { return buffer[id].element[0]; }

bool empty() {
  return buffer[id].length == 0;
}

bool full() {
  return buffer[id].length == BufferSize;
}

clock x;

g_id to_gid(d_id d, t_id t) {
    return d * Tasks + t;
}

time_t new_sporadic_period;

void completed() {
  complete[gid][tid] = true;

  load[task[gid][tid].curr_resource] -= task[gid][tid].wcet;

  task[gid][tid].curr_resource = -1;
}

time_t convertToTime(double x) {
    time_t result = 0;

    if (x >= 0) {
        while (x >= result) {
            result = result + 1;
        }
    } else {
        while (x <= result) {
            result = result - 1;
        }
    }

    return result;
}

void new_period() {

  complete[gid][tid] = false;

 /* if (dag[gid].sporadic == true)
  {
      int i = 0;
      // for (i = 0; i < dag[0].
// completed[]
      new_sporadic_period = task[gid][tid].min_period + 1;// convertToTime(random(Sporadic_Interval) + 1);
      task[gid][tid].max_period = task[gid][tid].min_period = new_sporadic_period;
  }*/

  task[gid][tid].curr_resource = -1;
}

time_t initialOffset() { return task[gid][tid].initial_offset; }
time_t minPeriod() { return task[gid][tid].min_period; }
time_t maxPeriod() { return task[gid][tid].max_period; }
time_t offset() { return task[gid][tid].offset; }
time_t deadline() { return task[gid][tid].deadline; }
time_t BCET() { return task[gid][tid].bcet; }
time_t WCET() { return task[gid][tid].wcet; }
time_t priotiry() { return task[gid][tid].pri; }
r_id resource() { return task[gid][tid].curr_resource; }

int[0,1] isRunning() {
  return (buffer[resource()].element[0] == tid? 1 : 0);
/*
  int i;
  for (i = 0; i < Procs-1; i++)
  {
    r_id r = task[gid][tid].resources[i];
    if (buffer[r].length > 0 && buffer[r].element[0] == tid)
    {
      return 1;
    }
  }
  return 0;
*/
}

int debug_resource_found= -1;

clock soonest_release;
clock remaining;

typedef struct {
  int first;
  int second;
} pair_t; 

typedef struct {
    int size;
    pair_t list[Tasks];
} pred_list_t;

typedef struct {
    int size;
    pair_t list[Tasks];
} edge_list_t;


pred_list_t predecessors;
edge_list_t predecessors_egdes;

int resource_id = -1;

int status=0;

void UpdateTaskResourceInfo(int g, int t, int r)
{
    task[g][t].curr_resource = r;
    load[r] += task[g][t].wcet;
    debug_resource_found = r;
}

int FindEdge(t_id pred, t_id succ)
{
    int i;

    for (i = 0; i < Tasks; i++)
    {
        if (task[gid][i].type == 1)
        {
            if (cons[gid][pred][i] > 0 &&
                prod[gid][i][succ] > 0)
            {
                return i;
            }
        }
    }

    return -1;
}

